contracts/ZetaphyOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Pyth's IPyth read surface, with PythStructs.Price's layout (the real Pyth and ZetaphyPythRelay both answer it).
interface IPythPrice {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
}

/// TwapRecorder's surface.
interface ITwapSource {
    struct Twap {
        uint256 avg0;
        uint256 avg1;
        uint64 from;
        uint64 newest;
        uint16 observations;
        uint128 minDepth;
        uint256 maxSegmentGapBps;
    }
    function consult(address pair, uint32 window) external view returns (Twap memory);
    function record(address pair) external returns (bool);
}

interface IPairTokens {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IDecimals {
    function decimals() external view returns (uint8);
}

/// @title ZetaphyOracle: one price per asset, or a clear revert
/// @notice price(asset) returns (value, updatedAt): `value` is the asset's price in
///         USD with 18 decimals (1e18 = $1 per whole token), `updatedAt` the oldest
///         source time behind it. When any guard fails it REVERTS with an error
///         naming what failed; it never returns a stale, lopsided or jumped value.
///         Sources, per asset (governance enables one or both):
///           a) a TWAP of a ZETAPHY DEX pair (TwapRecorder observations, the pair's
///              cumulative prices; the other token is a USD stablecoin counted at $1):
///              valid only over at least `window` seconds (from an observation at
///              most 2 x window old), with at least `minObservations` observations
///              in it, a pool depth (quote side, 18 decimals) of at least
///              `minLiquidity` at every observation and now, and no segment
///              between observations averaging more than `maxSegmentGapBps` away
///              from the window's average;
///           b) Pyth (IPyth.getPriceUnsafe; on ZETAPHY a ZetaphyPythRelay until Pyth
///              or a Hyperlane route is here): not older than `maxAge`, not dated
///              in the future, positive, confidence interval at most `maxConfBps`
///              of the price.
///         With both: they must agree within `maxDeviationBps` (else SourcesDeviate);
///         the value is Pyth's, anchored by the TWAP. Decimals are normalized
///         (token decimals, Pyth's exponent) to 18.
///         Circuit breaker: poke(asset) (anyone; a keeper, the relay) records a TWAP
///         observation and, if every guard passes, makes the live price the
///         reference. price() refuses a live price more than `maxChangeBps` from the
///         reference, or more than `maxWindowChangeBps` from the price at the start
///         of the current `changeWindow`. A poke that sees such a jump TRIPS the
///         breaker: the asset has no price until governance resets it (through the
///         timelock). poke() also logs DeviationTripped / StaleFeed / SourceProblem
///         for the bridge monitor (zetaphy bridge monitor).
///         Roles: governance (the ZetaphyTimelock) sets every parameter; guardians
///         (multisigs governance names) may pause a feed at once. Unpausing,
///         resetting a tripped breaker and any setting wait the timelock.
contract ZetaphyOracle {
    struct TwapConfig {
        address pair;            // zero: no TWAP source
        bool assetIsToken0;
        uint8 assetDecimals;
        uint8 quoteDecimals;
        uint32 window;           // seconds
        uint16 minObservations;
        uint16 maxSegmentGapBps;
        uint128 minLiquidity;    // quote-side depth, 18 decimals (USD)
    }
    struct PythConfig {
        bytes32 id;              // zero: no Pyth source
        uint32 maxAge;           // seconds
        uint16 maxConfBps;
    }
    struct Guards {
        uint16 maxDeviationBps;      // between the two sources
        uint16 maxChangeBps;         // from the reference (the last accepted price)
        uint16 maxWindowChangeBps;   // from the price at the start of the change window
        uint32 changeWindow;         // seconds
    }
    struct State {
        uint128 lastPrice;       // the reference (0: none yet, poke first)
        uint64 lastAt;
        bool paused;
        bool tripped;
        uint128 windowPrice;
        uint64 windowStart;
    }

    /// What went wrong with the live price (poke logs it; price() reverts with the matching error).
    enum Problem { None, NotConfigured, TwapUnavailable, TwapStale, TooFewObservations, LowLiquidity, TwapSpike,
        PythUnavailable, PythStale, PythInvalid, PythConfidence, SourcesDeviate }

    ITwapSource public immutable recorder;
    IPythPrice public pyth;
    address public governance;
    mapping(address => bool) public guardian;

    mapping(address => TwapConfig) public twapOf;
    mapping(address => PythConfig) public pythOf;
    mapping(address => Guards) public guardsOf;
    mapping(address => State) public stateOf;
    address[] private _assets;
    mapping(address => bool) public listed;

    uint256 public constant MAX_FUTURE = 60;   // seconds a Pyth publishTime may run ahead (clock skew)
    uint256 private constant BPS = 10_000;

    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event PythSet(address pyth);
    event TwapConfigured(address indexed asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity);
    event PythConfigured(address indexed asset, bytes32 id, uint32 maxAge, uint16 maxConfBps);
    event GuardsSet(address indexed asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow);
    event FeedPaused(address indexed asset, address indexed by);
    event FeedUnpaused(address indexed asset);
    event CircuitBreakerReset(address indexed asset);
    event Poked(address indexed asset, uint256 price, uint256 updatedAt);
    event DeviationTripped(address indexed asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    event StaleFeed(address indexed asset, uint8 source, uint256 updatedAt);   // source 1 TWAP, 2 Pyth
    event SourceProblem(address indexed asset, uint8 problem, uint256 a, uint256 b);
    event CircuitBreakerTripped(address indexed asset, uint256 price, uint256 ref, uint256 bps);

    error NotGovernance();
    error NotGuardian();
    error UnknownAsset(address asset);
    error FeedIsPaused(address asset);
    error BreakerTripped(address asset);
    error NoReference(address asset);
    error PriceJump(address asset, uint256 price, uint256 ref, uint256 bps);
    /// No source enabled, or no guards set (setGuards is required).
    error NotConfigured(address asset);
    error TwapUnavailable(address asset);
    error TwapStale(address asset, uint256 from);
    error TooFewObservations(address asset, uint256 have, uint256 need);
    error LowLiquidity(address asset, uint256 depth, uint256 need);
    error TwapSpike(address asset, uint256 bps, uint256 most);
    error PythUnavailable(address asset);
    error PythStale(address asset, uint256 publishTime);
    error PythInvalid(address asset);
    error PythConfidence(address asset, uint256 bps, uint256 most);
    error SourcesDeviate(address asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    error BadConfig();

    constructor(address governance_, ITwapSource recorder_, IPythPrice pyth_) {
        if (governance_ == address(0) || address(recorder_) == address(0)) revert BadConfig();
        governance = governance_;
        recorder = recorder_;
        pyth = pyth_;
        emit GovernanceSet(governance_);
        emit PythSet(address(pyth_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    // ---- governance (the timelock) ----

    function setGovernance(address g) external onlyGov { if (g == address(0)) revert BadConfig(); governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }
    /// The Pyth contract (ZetaphyPythRelay now; Pyth itself once deployed on ZETAPHY). Zero: no Pyth.
    function setPyth(IPythPrice p) external onlyGov { pyth = p; emit PythSet(address(p)); }

    /// The TWAP source of `asset`: a DEX pair of `asset` and a USD stablecoin (pair zero: off).
    function setTwap(address asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity) external onlyGov {
        TwapConfig memory c;
        if (pair != address(0)) {
            address t0 = IPairTokens(pair).token0();
            address t1 = IPairTokens(pair).token1();
            if (asset != t0 && asset != t1) revert BadConfig();
            if (window < 60 || minObservations < 2 || maxSegmentGapBps == 0 || minLiquidity == 0) revert BadConfig();
            c = TwapConfig(pair, asset == t0, IDecimals(asset).decimals(), IDecimals(asset == t0 ? t1 : t0).decimals(),
                window, minObservations, maxSegmentGapBps, minLiquidity);
            if (c.quoteDecimals > 18 || c.assetDecimals > 30) revert BadConfig();
        }
        twapOf[asset] = c;
        _configured(asset);
        emit TwapConfigured(asset, pair, window, minObservations, maxSegmentGapBps, minLiquidity);
    }

    /// The Pyth feed of `asset` (id zero: off).
    function setPythFeed(address asset, bytes32 id, uint32 maxAge, uint16 maxConfBps) external onlyGov {
        if (id != bytes32(0) && (maxAge == 0 || maxConfBps == 0 || maxConfBps > BPS)) revert BadConfig();
        pythOf[asset] = PythConfig(id, maxAge, maxConfBps);
        _configured(asset);
        emit PythConfigured(asset, id, maxAge, maxConfBps);
    }

    function setGuards(address asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow) external onlyGov {
        if (maxDeviationBps == 0 || maxChangeBps == 0 || maxWindowChangeBps < maxChangeBps || changeWindow == 0
            || maxDeviationBps > BPS || maxWindowChangeBps > BPS) revert BadConfig();
        guardsOf[asset] = Guards(maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
        _configured(asset);
        emit GuardsSet(asset, maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
    }

    /// Lifts a pause.
    function unpauseFeed(address asset) external onlyGov { stateOf[asset].paused = false; emit FeedUnpaused(asset); }

    /// Clears a tripped breaker and the reference: the next poke starts from the live price again.
    function resetCircuitBreaker(address asset) external onlyGov {
        State storage s = stateOf[asset];
        s.tripped = false;
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
        emit CircuitBreakerReset(asset);
    }

    function _configured(address asset) private {
        if (!listed[asset]) { listed[asset] = true; _assets.push(asset); }
        // A new source or guard starts from a fresh reference (the next poke).
        State storage s = stateOf[asset];
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
    }

    // ---- emergency: a guardian (or governance) stops a feed at once ----

    function pauseFeed(address asset) external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        stateOf[asset].paused = true;
        emit FeedPaused(asset, msg.sender);
    }

    // ---- consumers ----

    function assets() external view returns (address[] memory) { return _assets; }

    /// The asset's price in USD (18 decimals) and the time of its oldest source, or a revert naming why not.
    function price(address asset) external view returns (uint256 value, uint256 updatedAt) {
        if (!listed[asset]) revert UnknownAsset(asset);
        State memory s = stateOf[asset];
        if (s.paused) revert FeedIsPaused(asset);
        if (s.tripped) revert BreakerTripped(asset);
        Problem p; uint256 a; uint256 b;
        (value, updatedAt, p, a, b) = _live(asset);
        if (p != Problem.None) _fail(asset, p, a, b);
        if (s.lastPrice == 0) revert NoReference(asset);
        (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
        if (!ok) revert PriceJump(asset, value, ref, bps);
    }

    /// The live price and what is wrong with it, without the circuit breaker (for monitors and tests).
    function livePrice(address asset) external view returns (uint256 value, uint256 updatedAt, Problem problem, uint256 a, uint256 b) {
        return _live(asset);
    }

    /// Anyone: records a TWAP observation and, when every guard passes, moves the reference
    /// to the live price. A jump beyond the change limits trips the breaker. Returns whether
    /// the reference moved.
    function poke(address asset) external returns (bool) {
        if (!listed[asset]) revert UnknownAsset(asset);
        address pair = twapOf[asset].pair;
        if (pair != address(0)) { try recorder.record(pair) {} catch {} }
        State storage s = stateOf[asset];
        if (s.paused || s.tripped) return false;
        (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) = _live(asset);
        if (p != Problem.None) {
            if (p == Problem.SourcesDeviate) emit DeviationTripped(asset, a, b, _bps(a, b));
            else if (p == Problem.TwapStale) emit StaleFeed(asset, 1, a);
            else if (p == Problem.PythStale) emit StaleFeed(asset, 2, a);
            else emit SourceProblem(asset, uint8(p), a, b);
            return false;
        }
        if (s.lastPrice != 0) {
            if (block.timestamp >= uint256(s.windowStart) + guardsOf[asset].changeWindow) {
                s.windowPrice = s.lastPrice;
                s.windowStart = uint64(block.timestamp);
            }
            (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
            if (!ok) {
                s.tripped = true;
                emit CircuitBreakerTripped(asset, value, ref, bps);
                return false;
            }
        } else {
            s.windowPrice = uint128(value);
            s.windowStart = uint64(block.timestamp);
        }
        s.lastPrice = uint128(value);
        s.lastAt = uint64(at);
        emit Poked(asset, value, at);
        return true;
    }

    // ---- internals ----

    /// (reference, bps, ok): the live value against the reference and the window's start price.
    function _change(address asset, State memory s, uint256 value) private view returns (uint256, uint256, bool) {
        Guards memory g = guardsOf[asset];
        uint256 bps = _bps(value, s.lastPrice);
        if (bps > g.maxChangeBps) return (s.lastPrice, bps, false);
        if (s.windowPrice != 0 && block.timestamp < uint256(s.windowStart) + g.changeWindow) {
            uint256 wb = _bps(value, s.windowPrice);
            if (wb > g.maxWindowChangeBps) return (s.windowPrice, wb, false);
        }
        return (s.lastPrice, bps, true);
    }

    function _live(address asset) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        TwapConfig memory t = twapOf[asset];
        PythConfig memory y = pythOf[asset];
        if (t.pair == address(0) && (y.id == bytes32(0) || address(pyth) == address(0))) return (0, 0, Problem.NotConfigured, 0, 0);
        if (guardsOf[asset].maxChangeBps == 0) return (0, 0, Problem.NotConfigured, 0, 0); // guards are required
        uint256 twapValue; uint256 twapAt;
        if (t.pair != address(0)) {
            (twapValue, twapAt, p, a, b) = _twap(t);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        uint256 pythValue; uint256 pythAt;
        if (y.id != bytes32(0) && address(pyth) != address(0)) {
            (pythValue, pythAt, p, a, b) = _pyth(y);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        if (twapValue != 0 && pythValue != 0) {
            uint256 dev = _bps(twapValue, pythValue);
            if (dev > guardsOf[asset].maxDeviationBps) return (0, 0, Problem.SourcesDeviate, twapValue, pythValue);
            return (pythValue, pythAt < twapAt ? pythAt : twapAt, Problem.None, 0, 0);
        }
        return pythValue != 0 ? (pythValue, pythAt, Problem.None, 0, 0) : (twapValue, twapAt, Problem.None, 0, 0);
    }

    function _twap(TwapConfig memory t) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        ITwapSource.Twap memory w;
        try recorder.consult(t.pair, t.window) returns (ITwapSource.Twap memory r) { w = r; } catch { return (0, 0, Problem.TwapUnavailable, 0, 0); }
        if (block.timestamp - w.from > 2 * uint256(t.window)) return (0, 0, Problem.TwapStale, w.from, 0);
        if (w.observations < t.minObservations) return (0, 0, Problem.TooFewObservations, w.observations, t.minObservations);
        if (w.maxSegmentGapBps > t.maxSegmentGapBps) return (0, 0, Problem.TwapSpike, w.maxSegmentGapBps, t.maxSegmentGapBps);
        uint256 avg = t.assetIsToken0 ? w.avg0 : w.avg1;   // quote (raw) per asset (raw), UQ112x112
        if (avg == 0) return (0, 0, Problem.TwapUnavailable, 0, 0);
        // depth: sqrt(r0 r1) * sqrt(quote per asset) = the quote reserve; then 18 decimals
        uint256 depth = (uint256(w.minDepth) * _sqrt(avg)) >> 56;
        depth = depth * (10 ** uint256(18 - t.quoteDecimals));
        if (depth < t.minLiquidity) return (0, 0, Problem.LowLiquidity, depth, t.minLiquidity);
        value = _mulDiv(avg, 10 ** (uint256(t.assetDecimals) + 18), (10 ** uint256(t.quoteDecimals)) << 112);
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.TwapUnavailable, 0, 0);
        return (value, w.newest, Problem.None, 0, 0);
    }

    function _pyth(PythConfig memory y) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        IPythPrice.Price memory q;
        try pyth.getPriceUnsafe(y.id) returns (IPythPrice.Price memory r) { q = r; } catch { return (0, 0, Problem.PythUnavailable, 0, 0); }
        if (q.publishTime > block.timestamp + MAX_FUTURE) return (0, 0, Problem.PythInvalid, q.publishTime, 0);
        if (block.timestamp > q.publishTime && block.timestamp - q.publishTime > y.maxAge) return (0, 0, Problem.PythStale, q.publishTime, 0);
        if (q.price <= 0 || q.expo < -30 || q.expo > 12) return (0, 0, Problem.PythInvalid, 0, 0);
        uint256 raw = uint256(uint64(q.price));
        uint256 confBps = _mulDiv(uint256(q.conf), BPS, raw);
        if (confBps > y.maxConfBps) return (0, 0, Problem.PythConfidence, confBps, y.maxConfBps);
        int256 e = int256(q.expo) + 18;
        value = e >= 0 ? raw * (10 ** uint256(e)) : raw / (10 ** uint256(-e));
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.PythInvalid, 0, 0);
        return (value, q.publishTime > block.timestamp ? block.timestamp : q.publishTime, Problem.None, 0, 0);
    }

    function _fail(address asset, Problem p, uint256 a, uint256 b) private pure {
        if (p == Problem.NotConfigured) revert NotConfigured(asset);
        if (p == Problem.TwapUnavailable) revert TwapUnavailable(asset);
        if (p == Problem.TwapStale) revert TwapStale(asset, a);
        if (p == Problem.TooFewObservations) revert TooFewObservations(asset, a, b);
        if (p == Problem.LowLiquidity) revert LowLiquidity(asset, a, b);
        if (p == Problem.TwapSpike) revert TwapSpike(asset, a, b);
        if (p == Problem.PythUnavailable) revert PythUnavailable(asset);
        if (p == Problem.PythStale) revert PythStale(asset, a);
        if (p == Problem.PythInvalid) revert PythInvalid(asset);
        if (p == Problem.PythConfidence) revert PythConfidence(asset, a, b);
        revert SourcesDeviate(asset, a, b, _bps(a, b));
    }

    /// |x - y| / min(x, y), in bps.
    function _bps(uint256 x, uint256 y) private pure returns (uint256) {
        uint256 lo = x < y ? x : y;
        if (lo == 0) return type(uint256).max;
        return _mulDiv(x > y ? x - y : y - x, BPS, lo);
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/ZetaphyOutbox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZetaphyOutbox: an append-only Merkle commitment of outgoing messages (ZETAPHY side)
/// @notice Why a commitment contract: a CometBFT header commits to the state (app_hash, an IAVL
///         multistore root) but NOT to EVM logs (last_results_hash only covers code, data and gas
///         of each tx result, and receipts/blooms live in a transient store). So events cannot be
///         proven to Ethereum from a header. Instead every message is appended to a SHA-256 Merkle
///         tree (depth 32, the Ethereum deposit-contract construction) and the root is kept in
///         STORAGE SLOT 0. The slot is in the evm IAVL store under 0x02 || address || slot, so
///         app_hash -> multistore proof -> IAVL proof -> slot 0 -> Merkle path proves a message.
///
///         root  = sha256(treeRoot || uint256(count))
///         leaf  = sha256(abi.encode(LEAF_TAG, block.chainid, address(this), nonce, sender,
///                                   dstChainId, receiver, sha256(payload)))
///         The nonce is the leaf index (0, 1, 2, ...): replay protection on the other side is a
///         bitmap of consumed nonces. No owner, no upgrade, no way to remove a message.
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract ZetaphyOutbox {
    bytes32 public root;              // slot 0: proven by ZetaphyBridgeInbox (never zero after the constructor)
    uint64 public count;              // slot 1
    bytes32[32] private branch;       // slots 2..33

    bytes32 public constant LEAF_TAG = keccak256("zetaphy/outbox/v1");
    uint256 public constant DEPTH = 32;

    event MessageSent(uint64 indexed nonce, address indexed sender, uint256 indexed dstChainId, address receiver, bytes payload, bytes32 leaf, bytes32 root);

    constructor() {
        root = _root();
    }

    function send(uint256 dstChainId, address receiver, bytes calldata payload) external returns (uint64 nonce) {
        nonce = count;
        require(nonce < type(uint32).max, "full");
        bytes32 leaf = leafHash(block.chainid, address(this), nonce, msg.sender, dstChainId, receiver, sha256(payload));
        uint256 size = uint256(nonce) + 1;
        bytes32 node = leaf;
        for (uint256 h = 0; h < DEPTH; h++) {
            if (size & 1 == 1) { branch[h] = node; break; }
            node = sha256(abi.encodePacked(branch[h], node));
            size >>= 1;
        }
        count = nonce + 1;
        bytes32 r = _root();
        root = r;
        emit MessageSent(nonce, msg.sender, dstChainId, receiver, payload, leaf, r);
    }

    function leafHash(uint256 srcChainId, address outbox, uint64 nonce, address sender, uint256 dstChainId, address receiver, bytes32 payloadHash)
        public pure returns (bytes32)
    {
        return sha256(abi.encode(LEAF_TAG, srcChainId, outbox, nonce, sender, dstChainId, receiver, payloadHash));
    }

    function _root() private view returns (bytes32) {
        bytes32 node;
        bytes32 zero;
        uint256 size = count;
        for (uint256 h = 0; h < DEPTH; h++) {
            node = size & 1 == 1 ? sha256(abi.encodePacked(branch[h], node)) : sha256(abi.encodePacked(node, zero));
            zero = sha256(abi.encodePacked(zero, zero));
            size >>= 1;
        }
        return sha256(abi.encodePacked(node, uint256(count)));
    }
}

interface IZetaphyOutbox {
    function send(uint256 dstChainId, address receiver, bytes calldata payload) external returns (uint64);
}

interface IERC20Lockable {
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

/// @title ZetaphyLockbox: locks a token on ZETAPHY and sends "release `amount` to `recipient`"
///        through the outbox to one fixed receiver on one fixed destination chain.
/// @notice The tokens stay here (the way back is a mirror of this bridge, not in this prototype).
///         Everything is fixed at deployment: no admin.
contract ZetaphyLockbox {
    IERC20Lockable public immutable token;
    IZetaphyOutbox public immutable outbox;
    uint256 public immutable dstChainId;
    address public immutable dstReceiver;

    event Locked(uint64 indexed nonce, address indexed from, address indexed recipient, uint256 amount);

    constructor(IERC20Lockable token_, IZetaphyOutbox outbox_, uint256 dstChainId_, address dstReceiver_) {
        token = token_;
        outbox = outbox_;
        dstChainId = dstChainId_;
        dstReceiver = dstReceiver_;
    }

    function lock(uint256 amount, address recipient) external returns (uint64 nonce) {
        require(amount > 0 && recipient != address(0), "lock");
        require(token.transferFrom(msg.sender, address(this), amount), "transfer");
        nonce = outbox.send(dstChainId, dstReceiver, abi.encode(recipient, amount));
        emit Locked(nonce, msg.sender, recipient, amount);
    }
}

contracts/ZetaphyPQCheques.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPQChequeERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

/// @title ZetaphyPQCheques: offline cheques signed with ML-DSA-44 (testnet, not audited)
/// @notice The post-quantum twin of ZetaphyCheques (same channels, same rules, same events where they fit),
///         a separate contract so the deployed ZetaphyCheques and everything that reads it stay as they are.
///         The difference: a channel names an ML-DSA-44 public key (FIPS 204) instead of an ECDSA signer, and
///         cheques are checked by ZETAPHY's precompile at 0x…0900, the PQSettlement / QuantumWallet path.
///         No ecrecover anywhere: a quantum computer that derives secp256k1 keys cannot forge a cheque.
///
///         open(payee, token, amount, expiry, signerKey): signerKey is the 1312-byte ML-DSA-44 public key;
///         the contract keeps keccak256(signerKey) and emits the key itself (SignerKey event), so the payee
///         can read it from the chain once and check cheques offline afterwards.
///
///         A cheque: the signer signs chequeDigest(channelId, cumulativeAmount) =
///           keccak256(abi.encode("ZETAPHY PQCheques cheque v1", chainid, this, channelId, cumulativeAmount)),
///         the TOTAL promised so far; cash(id, cumulative, pk, sig) pays the payee the part not cashed yet,
///         never more than the deposit. Closing, challenge period, release, top-up and extend are exactly
///         those of ZetaphyCheques.
///
///         What stays classical: the payer funds the channel and closes it with its own account, and the
///         payee receives at its address. A quantum attacker who derives the payer's ECDSA key can do what
///         the payer can (top up, extend, close after expiry), not forge cheques; to make those steps
///         quantum-safe too, open the channel from a QuantumWallet or a native ML-DSA account.
///
///         No owner, no fee, no upgrade. Plain ERC-20s; fee-on-transfer tokens are refused. Checks-effects-
///         interactions and nonReentrant on every entry point.
contract ZetaphyPQCheques {
    struct Channel {
        address payer;
        uint64 expiry;     // the payer may start closing from here
        uint64 closeAt;    // 0 = open; else the end of the challenge period
        address payee;
        address token;     // address(0) = native ZETAPHY
        bytes32 signerKey; // keccak256 of the ML-DSA-44 public key whose cheques count
        uint256 deposit;   // everything deposited
        uint256 paid;      // everything cashed by the payee
        bool done;         // the payer took the remainder: the channel is over
    }

    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant VARIANT = 44;
    uint256 public constant PK_BYTES = 1312;
    uint256 public constant CHALLENGE_PERIOD = 24 hours;
    uint256 public constant MAX_DURATION = 366 days;

    uint256 public channelCount;
    mapping(uint256 => Channel) public channels;
    uint256 private locked = 1;

    event ChannelOpened(uint256 indexed id, address indexed payer, address indexed payee, address token, uint256 amount, uint64 expiry, bytes32 signerKey);
    event SignerKey(uint256 indexed id, bytes publicKey);
    event ToppedUp(uint256 indexed id, uint256 amount, uint256 deposit);
    event Extended(uint256 indexed id, uint64 expiry);
    event Cashed(uint256 indexed id, address indexed payee, uint256 cumulative, uint256 amount, address submitter);
    event CloseStarted(uint256 indexed id, uint64 closeAt);
    event Released(uint256 indexed id);
    event Withdrawn(uint256 indexed id, address indexed payer, uint256 amount);

    error BadChannel();
    error NotPayer();
    error NotPayee();
    error BadAmount();
    error BadExpiry();
    error BadValue();
    error Closing();
    error NotClosing();
    error NotExpired();
    error ChallengeOpen();
    error ChannelDone();
    error WrongKey();
    error BadSignature();
    error NothingToCash();
    error FeeOnTransfer();
    error TokenFailed();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    /// The 32 bytes the channel's ML-DSA key signs for a cheque (src/qsafe/offline.js pqChequeDigest).
    function chequeDigest(uint256 id, uint256 cumulative) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY PQCheques cheque v1", block.chainid, address(this), id, cumulative));
    }

    // ------------------------------------------------------------------ payer

    /// Opens a channel to `payee` with `amount` of `token` (0 = native: send it as msg.value), cheques
    /// signed by the ML-DSA-44 key `signerKey`, closable from `expiry`. Returns the channel id (1, 2, ...).
    function open(address payee, address token, uint256 amount, uint64 expiry, bytes calldata signerKey)
        external payable nonReentrant returns (uint256 id)
    {
        if (payee == address(0) || payee == msg.sender || signerKey.length != PK_BYTES) revert BadChannel();
        if (amount == 0) revert BadAmount();
        if (expiry <= block.timestamp || expiry > block.timestamp + MAX_DURATION) revert BadExpiry();
        bytes32 keyHash = keccak256(signerKey);
        id = ++channelCount;
        channels[id] = Channel({ payer: msg.sender, expiry: expiry, closeAt: 0, payee: payee, token: token, signerKey: keyHash,
            deposit: amount, paid: 0, done: false });
        emit ChannelOpened(id, msg.sender, payee, token, amount, expiry, keyHash);
        emit SignerKey(id, signerKey);
        _pullIn(token, amount);
    }

    /// Adds to the deposit (payer only, not once closing).
    function topUp(uint256 id, uint256 amount) external payable nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (amount == 0) revert BadAmount();
        c.deposit += amount;
        emit ToppedUp(id, amount, c.deposit);
        _pullIn(c.token, amount);
    }

    /// Moves the expiry later (payer only, not once closing).
    function extend(uint256 id, uint64 expiry) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (expiry <= c.expiry || expiry > block.timestamp + MAX_DURATION) revert BadExpiry();
        c.expiry = expiry;
        emit Extended(id, expiry);
    }

    /// After the expiry: starts the challenge period, during which the payee can still cash.
    function startClose(uint256 id) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt != 0) revert Closing();
        if (block.timestamp < c.expiry) revert NotExpired();
        uint64 at = uint64(block.timestamp + CHALLENGE_PERIOD);
        c.closeAt = at;
        emit CloseStarted(id, at);
    }

    /// After the challenge period (or a release): the payer takes what was not cashed.
    function withdraw(uint256 id) external nonReentrant {
        Channel storage c = _payerChannel(id);
        if (c.closeAt == 0) revert NotClosing();
        if (block.timestamp < c.closeAt) revert ChallengeOpen();
        c.done = true;
        uint256 rest = c.deposit - c.paid;
        emit Withdrawn(id, c.payer, rest);
        if (rest != 0) _pay(c.token, c.payer, rest);
    }

    // ------------------------------------------------------------------ payee (and anyone)

    /// Cashes an ML-DSA-signed cheque: pays the payee min(cumulative, deposit) minus what it was already paid.
    /// `pk` is the channel's public key (keccak256(pk) == signerKey). Anyone may submit; the payee is paid.
    function cash(uint256 id, uint256 cumulative, bytes calldata pk, bytes calldata sig) external nonReentrant returns (uint256 amount) {
        Channel storage c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (c.done) revert ChannelDone();
        if (c.closeAt != 0 && block.timestamp >= c.closeAt) revert ChannelDone();
        if (keccak256(pk) != c.signerKey) revert WrongKey();
        if (!_pqValid(chequeDigest(id, cumulative), pk, sig)) revert BadSignature();
        uint256 upTo = cumulative < c.deposit ? cumulative : c.deposit;
        if (upTo <= c.paid) revert NothingToCash();
        amount = upTo - c.paid;
        c.paid = upTo;
        emit Cashed(id, c.payee, cumulative, amount, msg.sender);
        _pay(c.token, c.payee, amount);
    }

    /// The payee gives up the rest of the channel (after cashing): the payer may withdraw at once.
    function release(uint256 id) external nonReentrant {
        Channel storage c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (msg.sender != c.payee) revert NotPayee();
        if (c.done) revert ChannelDone();
        c.closeAt = uint64(block.timestamp);
        emit Released(id);
    }

    /// What cash(id, cumulative, …) would pay now with a valid cheque (0 if nothing / closed).
    function cashable(uint256 id, uint256 cumulative) external view returns (uint256) {
        Channel storage c = channels[id];
        if (c.payer == address(0) || c.done || (c.closeAt != 0 && block.timestamp >= c.closeAt)) return 0;
        uint256 upTo = cumulative < c.deposit ? cumulative : c.deposit;
        return upTo > c.paid ? upTo - c.paid : 0;
    }

    // ------------------------------------------------------------------ internals

    function _payerChannel(uint256 id) private view returns (Channel storage c) {
        c = channels[id];
        if (c.payer == address(0)) revert BadChannel();
        if (msg.sender != c.payer) revert NotPayer();
        if (c.done) revert ChannelDone();
    }

    function _pullIn(address token, uint256 amount) private {
        if (token == address(0)) {
            if (msg.value != amount) revert BadValue();
            return;
        }
        if (msg.value != 0) revert BadValue();
        if (token.code.length == 0) revert TokenFailed();
        uint256 before = IPQChequeERC20(token).balanceOf(address(this));
        _safe(token, abi.encodeCall(IPQChequeERC20.transferFrom, (msg.sender, address(this), amount)));
        if (IPQChequeERC20(token).balanceOf(address(this)) - before != amount) revert FeeOnTransfer();
    }

    function _pay(address token, address to, uint256 amount) private {
        if (token == address(0)) {
            (bool ok, ) = to.call{value: amount}("");
            if (!ok) revert SendFailed();
        } else {
            _safe(token, abi.encodeCall(IPQChequeERC20.transfer, (to, amount)));
        }
    }

    /// ML-DSA-44 verify through the precompile (variant ‖ digest ‖ pk ‖ sig -> uint256(1)), as PQSettlement.
    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        if (pk.length != PK_BYTES) return false; // fixed key length: the key / signature split cannot shift
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(VARIANT, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _safe(address token, bytes memory data) private {
        if (token.code.length == 0) revert TokenFailed();
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || !abi.decode(ret, (bool))))) revert TokenFailed();
    }
}

contracts/ZetaphyPQOfflineOrders.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPQOrdersERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

/// The ZETAPHY Swap router (zetaphy-dex/contracts/ZetaphyRouter.sol, Uniswap V2 names).
interface IPQOrdersRouter {
    function WETH() external view returns (address);
    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external returns (uint256[] memory amounts);
}

interface IPQOrdersWrapped {
    function withdraw(uint256) external;
}

/// @title ZetaphyPQOfflineOrders: offline swap orders signed with ML-DSA-44, filled by anyone (testnet, not audited)
/// @notice The post-quantum twin of ZetaphyOfflineOrders, a separate contract so the deployed one and its users
///         stay as they are. Same Order, same fill rules (all or nothing, the relayer picks the route and earns
///         `relayerFee` in tokenOut, the maker's minimum is checked on what it actually received, native
///         ZETAPHY out is unwrapped, one nonce per order in a per-maker bitmap, cancel / cancelWord).
///
///         The difference: no ecrecover. A maker (any account: a QuantumWallet, a native ML-DSA account's
///         0x address, or an EOA) first names its ML-DSA-44 key with setPQKey(keccak256(publicKey)); orders
///         are then signed offline with that key over
///           digest(o) = keccak256(abi.encode("ZETAPHY PQOfflineOrders order v1", chainid, this, orderHash(o)))
///         and fill(o, pk, sig, path) checks keccak256(pk) == pqKeyOf[maker] and the signature with ZETAPHY's
///         ML-DSA precompile at 0x…0900 (the PQSettlement / QuantumWallet path). Rotating or clearing the key
///         (setPQKey again) voids every unfilled order signed with the old key.
///
///         Honest limits: tokenIn is pulled from the maker with transferFrom, so the allowance and the balance
///         are only as safe as the maker's account. For an end-to-end quantum-safe maker, use a QuantumWallet in
///         post-quantum-only mode (it calls setPQKey and approve through execute) or a native ML-DSA account.
///         There is no EIP-2612 permit path here: permits are ECDSA signatures.
contract ZetaphyPQOfflineOrders {
    struct Order {
        address maker;
        address tokenIn;
        address tokenOut;     // address(0) = native ZETAPHY
        uint256 amountIn;
        uint256 minAmountOut; // what the maker gets at least, after the relayer fee
        uint256 deadline;
        uint256 nonce;
        uint256 relayerFee;   // in tokenOut, to whoever fills
    }

    bytes32 public constant ORDER_TYPEHASH = keccak256(
        "Order(address maker,address tokenIn,address tokenOut,uint256 amountIn,uint256 minAmountOut,uint256 deadline,uint256 nonce,uint256 relayerFee)"
    );
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant VARIANT = 44;
    uint256 public constant PK_BYTES = 1312;
    uint256 public constant MAX_HOPS = 3;

    address public immutable router;
    address public immutable wrapped;

    /// maker => keccak256 of its ML-DSA-44 public key (0 = none: its orders cannot fill)
    mapping(address => bytes32) public pqKeyOf;
    /// maker => word position (nonce >> 8) => bits of used nonces (nonce & 255)
    mapping(address => mapping(uint256 => uint256)) public nonceBitmap;
    uint256 private locked = 1;

    event PQKeySet(address indexed maker, bytes32 keyHash);
    event OrderFilled(address indexed maker, uint256 indexed nonce, bytes32 indexed orderHash, address relayer,
        uint256 amountIn, uint256 amountOut, uint256 relayerFee);
    event NonceCancelled(address indexed maker, uint256 wordPos, uint256 mask);

    error Expired();
    error NonceUsed();
    error NoKey();
    error WrongKey();
    error BadSignature();
    error BadOrder();
    error BadPath();
    error FeeOnTransfer();
    error InsufficientOutput(uint256 got, uint256 wanted);
    error TokenFailed();
    error SendFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    constructor(address router_) {
        router = router_;
        wrapped = IPQOrdersRouter(router_).WETH();
    }

    /// Only the wrapped coin pays native coins in here (when it unwraps).
    receive() external payable {
        if (msg.sender != wrapped) revert SendFailed();
    }

    // ------------------------------------------------------------------ digests

    function orderHash(Order calldata o) public pure returns (bytes32) {
        return keccak256(abi.encode(ORDER_TYPEHASH, o.maker, o.tokenIn, o.tokenOut, o.amountIn, o.minAmountOut, o.deadline, o.nonce, o.relayerFee));
    }

    /// The 32 bytes the maker's ML-DSA key signs (src/qsafe/offline.js pqOrderDigest).
    function digest(Order calldata o) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY PQOfflineOrders order v1", block.chainid, address(this), orderHash(o)));
    }

    function isNonceUsed(address maker, uint256 nonce) public view returns (bool) {
        return nonceBitmap[maker][nonce >> 8] & (1 << (nonce & 0xff)) != 0;
    }

    // ------------------------------------------------------------------ maker

    /// Names the caller's ML-DSA-44 key (keccak256 of the 1312-byte public key); 0 clears it.
    function setPQKey(bytes32 keyHash) external {
        pqKeyOf[msg.sender] = keyHash;
        emit PQKeySet(msg.sender, keyHash);
    }

    function cancel(uint256 nonce) external {
        uint256 mask = 1 << (nonce & 0xff);
        nonceBitmap[msg.sender][nonce >> 8] |= mask;
        emit NonceCancelled(msg.sender, nonce >> 8, mask);
    }

    /// Burns every nonce of word `wordPos` whose bit is set in `mask`.
    function cancelWord(uint256 wordPos, uint256 mask) external {
        nonceBitmap[msg.sender][wordPos] |= mask;
        emit NonceCancelled(msg.sender, wordPos, mask);
    }

    // ------------------------------------------------------------------ anyone (the relayer)

    /// Fills an ML-DSA-signed order; returns what the maker received. Simulate it with eth_call first.
    function fill(Order calldata o, bytes calldata pk, bytes calldata sig, address[] calldata path)
        external nonReentrant returns (uint256 toMaker)
    {
        address outToken = _checkOrder(o, path);
        bytes32 h = _checkSig(o, pk, sig);
        _useNonce(o.maker, o.nonce);
        return _swapAndPay(o, path, outToken, h);
    }

    // ------------------------------------------------------------------ internals

    /// Deadline, order shape and route; returns the token the swap ends in.
    function _checkOrder(Order calldata o, address[] calldata path) private view returns (address outToken) {
        if (block.timestamp > o.deadline) revert Expired();
        if (o.maker == address(0) || o.amountIn == 0 || o.tokenIn == address(0) || o.tokenIn == o.tokenOut || o.tokenIn == address(this)) revert BadOrder();
        outToken = o.tokenOut == address(0) ? wrapped : o.tokenOut;
        if (outToken == o.tokenIn) revert BadOrder();
        _checkPath(path, o.tokenIn, outToken);
    }

    function _swapAndPay(Order calldata o, address[] calldata path, address outToken, bytes32 h) private returns (uint256 toMaker) {
        uint256 got = _pullAndSwap(o, path, outToken);
        toMaker = got - o.relayerFee;
        _payOut(o, outToken, got, toMaker);
        emit OrderFilled(o.maker, o.nonce, h, msg.sender, o.amountIn, toMaker, o.relayerFee);
    }

    /// The maker's named key signed this order; returns its orderHash.
    function _checkSig(Order calldata o, bytes calldata pk, bytes calldata sig) private view returns (bytes32 h) {
        bytes32 key = pqKeyOf[o.maker];
        if (key == bytes32(0)) revert NoKey();
        if (keccak256(pk) != key) revert WrongKey();
        h = orderHash(o);
        if (!_pqValid(keccak256(abi.encode("ZETAPHY PQOfflineOrders order v1", block.chainid, address(this), h)), pk, sig)) revert BadSignature();
    }

    function _pullAndSwap(Order calldata o, address[] calldata path, address outToken) private returns (uint256 got) {
        IPQOrdersERC20 tin = IPQOrdersERC20(o.tokenIn);
        uint256 inBefore = tin.balanceOf(address(this));
        _safe(o.tokenIn, abi.encodeCall(IPQOrdersERC20.transferFrom, (o.maker, address(this), o.amountIn)));
        if (tin.balanceOf(address(this)) - inBefore != o.amountIn) revert FeeOnTransfer();
        uint256 want = o.minAmountOut + o.relayerFee;
        uint256 outBefore = IPQOrdersERC20(outToken).balanceOf(address(this));
        _safe(o.tokenIn, abi.encodeCall(IPQOrdersERC20.approve, (router, o.amountIn)));
        _swap(o, path, outToken, want);
        _safe(o.tokenIn, abi.encodeCall(IPQOrdersERC20.approve, (router, 0)));
        if (tin.balanceOf(address(this)) != inBefore) revert BadPath(); // the router took all of amountIn
        got = IPQOrdersERC20(outToken).balanceOf(address(this)) - outBefore;
        if (got < want) revert InsufficientOutput(got, want);
    }

    function _swap(Order calldata o, address[] calldata path, address outToken, uint256 want) private {
        uint256[] memory amounts;
        if (path.length != 0) {
            amounts = IPQOrdersRouter(router).swapExactTokensForTokens(o.amountIn, want, path, address(this), o.deadline);
        } else {
            address[] memory direct = new address[](2);
            direct[0] = o.tokenIn;
            direct[1] = outToken;
            amounts = IPQOrdersRouter(router).swapExactTokensForTokens(o.amountIn, want, direct, address(this), o.deadline);
        }
        // the router's own report must meet `want` too; _pullAndSwap then measures what actually arrived
        uint256 reported = amounts.length == 0 ? 0 : amounts[amounts.length - 1];
        if (reported < want) revert InsufficientOutput(reported, want);
    }

    function _payOut(Order calldata o, address outToken, uint256 got, uint256 toMaker) private {
        if (o.tokenOut == address(0)) {
            IPQOrdersWrapped(wrapped).withdraw(got);
            // WZETAPHY pays the coins in; ZETAPHY's native ERC-20 already holds them (its withdraw is a no-op)
            if (address(this).balance < got) revert TokenFailed();
            _sendNative(o.maker, toMaker);
            if (o.relayerFee != 0) _sendNative(msg.sender, o.relayerFee);
            return;
        }
        uint256 makerBefore = IPQOrdersERC20(outToken).balanceOf(o.maker);
        _safe(outToken, abi.encodeCall(IPQOrdersERC20.transfer, (o.maker, toMaker)));
        uint256 makerGot = IPQOrdersERC20(outToken).balanceOf(o.maker) - makerBefore;
        if (makerGot < o.minAmountOut) revert InsufficientOutput(makerGot, o.minAmountOut);
        if (o.relayerFee != 0) _safe(outToken, abi.encodeCall(IPQOrdersERC20.transfer, (msg.sender, o.relayerFee)));
    }

    function _checkPath(address[] calldata path, address tokenIn, address outToken) private pure {
        if (path.length == 0) return;
        if (path.length < 2 || path.length > MAX_HOPS + 1 || path[0] != tokenIn || path[path.length - 1] != outToken) revert BadPath();
    }

    function _useNonce(address maker, uint256 nonce) private {
        uint256 bit = 1 << (nonce & 0xff);
        uint256 word = nonceBitmap[maker][nonce >> 8];
        if (word & bit != 0) revert NonceUsed();
        nonceBitmap[maker][nonce >> 8] = word | bit;
    }

    function _sendNative(address to, uint256 amount) private {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert SendFailed();
    }

    /// ML-DSA-44 verify through the precompile (variant ‖ digest ‖ pk ‖ sig -> uint256(1)), as PQSettlement.
    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        if (pk.length != PK_BYTES) return false;
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(VARIANT, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _safe(address token, bytes memory data) private {
        if (token.code.length == 0) revert TokenFailed();
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || !abi.decode(ret, (bool))))) revert TokenFailed();
    }
}

contracts/ZetaphyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title BZTPHY: ZETAPHY testnet reward points
/// @notice People who run ZETAPHY validators and Neuro runners on the testnet earn BZTPHY.
///         When mainnet launches, BZTPHY balances at the freeze become ZETAPHY at mainnet genesis
///         (a share of a fixed pool; see zetaphy-chain/rewards/README.md).
///         BZTPHY cannot be transferred, approved or sold: it shows who did the work, not who bought it.
///         Wallets still show the balance (balanceOf, totalSupply, name, symbol, decimals, Transfer events).
contract ZetaphyPoints {
    string public constant name = "ZETAPHY Testnet Reward Points";
    string public constant symbol = "BZTPHY";
    uint8 public constant decimals = 18;

    address public owner;          // governance: sets the minter, the cap, revokes, freezes
    address public pendingOwner;
    address public minter;         // the daily award job
    uint256 public epochCap;       // most BZTPHY one epoch (UTC day) may award in total
    bool public frozen;            // after the freeze nothing changes: the balances are the snapshot

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(uint32 => uint256) public awardedInEpoch;
    mapping(uint32 => mapping(address => bool)) public awarded;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Awarded(uint32 indexed epoch, address indexed to, uint256 amount, bytes32 reason);
    event Revoked(address indexed from, uint256 amount, bytes32 reason);
    event MinterSet(address minter);
    event EpochCapSet(uint256 cap);
    event OwnershipTransferStarted(address indexed to);
    event OwnershipTransferred(address indexed from, address indexed to);
    event Frozen(uint256 totalSupply);

    error NotOwner();
    error NotMinter();
    error IsFrozen();
    error NonTransferable();
    error LengthMismatch();
    error AlreadyAwarded(uint32 epoch, address to);
    error OverEpochCap(uint32 epoch);
    error ZeroAddress();

    constructor(address owner_, address minter_, uint256 epochCap_) {
        if (owner_ == address(0)) revert ZeroAddress();
        owner = owner_;
        minter = minter_;
        epochCap = epochCap_;
        emit OwnershipTransferred(address(0), owner_);
        emit MinterSet(minter_);
        emit EpochCapSet(epochCap_);
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier notFrozen() {
        if (frozen) revert IsFrozen();
        _;
    }

    /// @notice Awards one epoch's points. Each address gets at most one award per epoch, so a
    ///         job that runs twice cannot pay twice, and an epoch never exceeds epochCap (a stolen
    ///         minter key can mint at most one cap per day, and the owner can revoke it).
    function award(uint32 epoch, address[] calldata to, uint256[] calldata amounts, bytes32 reason) external notFrozen {
        if (msg.sender != minter) revert NotMinter();
        if (to.length != amounts.length) revert LengthMismatch();
        uint256 before = awardedInEpoch[epoch];
        uint256 total = before;
        for (uint256 i = 0; i < to.length; i++) {
            address a = to[i];
            if (a == address(0)) revert ZeroAddress();
            if (awarded[epoch][a]) revert AlreadyAwarded(epoch, a);
            awarded[epoch][a] = true;
            total += amounts[i];
            balanceOf[a] += amounts[i];
            emit Transfer(address(0), a, amounts[i]);
            emit Awarded(epoch, a, amounts[i], reason);
        }
        if (total > epochCap) revert OverEpochCap(epoch);
        awardedInEpoch[epoch] = total;
        totalSupply += total - before;
    }

    /// @notice Takes points back (cheating, e.g. one person running many fake validators).
    function revoke(address from, uint256 amount, bytes32 reason) external onlyOwner notFrozen {
        uint256 b = balanceOf[from];
        if (amount > b) amount = b;
        balanceOf[from] = b - amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
        emit Revoked(from, amount, reason);
    }

    function setMinter(address m) external onlyOwner notFrozen {
        minter = m;
        emit MinterSet(m);
    }

    function setEpochCap(uint256 cap) external onlyOwner notFrozen {
        epochCap = cap;
        emit EpochCapSet(cap);
    }

    /// @notice Ends the program for good: the balances now are what mainnet genesis uses.
    function freeze() external onlyOwner notFrozen {
        frozen = true;
        minter = address(0);
        emit Frozen(totalSupply);
    }

    function transferOwnership(address to) external onlyOwner {
        pendingOwner = to;
        emit OwnershipTransferStarted(to);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ---- ERC-20 surface that refuses to move points --------------------------------------
    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function transfer(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function approve(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }
}

contracts/ZetaphyPythRelay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice The part of Pyth's IPyth (pyth-sdk-solidity) ZETAPHY reads and writes,
///         with Pyth's own struct layout (PythStructs.Price / PriceFeed): the
///         ABI is the same as the real Pyth contract's, so ZetaphyOracle can be
///         pointed at real Pyth later (ZetaphyOracle.setPyth, through the timelock).
interface IPythLike {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    struct PriceFeed {
        bytes32 id;
        Price price;
        Price emaPrice;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory);
    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory);
    function priceFeedExists(bytes32 id) external view returns (bool);
    function getUpdateFee(bytes[] calldata updateData) external view returns (uint256);
    function updatePriceFeeds(bytes[] calldata updateData) external payable;
}

/// @title ZetaphyPythRelay: Pyth prices on ZETAPHY before Pyth itself is here
/// @notice Pyth has no contract on ZETAPHY yet. Real Pyth checks each update
///         against Wormhole guardian signatures; this relay instead accepts an
///         update only when `threshold` distinct relayers (keys governance names)
///         submitted exactly the same one. Updates use Pyth's public format, the
///         one Pyth's MockPyth.createPriceFeedUpdateData builds:
///             abi.encode(PythStructs.PriceFeed feed, uint64 prevPublishTime)
///         so a relayer forwards what it reads from Pyth (Hermes) unchanged.
///         Like Pyth: an older update than the stored one is ignored (not an
///         error), the PriceFeedUpdate event is Pyth's, and reads revert with
///         PriceFeedNotFound / StalePrice. Unlike Pyth: the update fee is 0 and
///         sending value is refused.
///         Trust: the relayers (and governance, which names them) can publish any
///         price. ZetaphyOracle does not trust it alone: it checks staleness, the
///         confidence interval, the deviation from the DEX TWAP and a circuit
///         breaker. Later, either point ZetaphyOracle at real Pyth, or make a
///         Hyperlane receiver (a contract whose handle() takes Pyth updates from
///         a Hyperlane message out of a chain where Pyth verified them) the only
///         relayer, with threshold 1. Docs: zetaphy-network/README.md (oracle).
///         Governance: the ZetaphyTimelock.
contract ZetaphyPythRelay is IPythLike {
    address public governance;
    mapping(address => bool) public isRelayer;
    uint256 public relayerCount;
    uint8 public threshold;
    /// The furthest in the future a publishTime may be (clock skew).
    uint256 public constant MAX_FUTURE = 60;

    mapping(bytes32 => PriceFeed) private _feeds;
    /// keccak256(update) => relayer => submitted (an update is accepted once threshold relayers sent it)
    mapping(bytes32 => mapping(address => bool)) public submitted;
    /// Who submitted each update, so only those still relayers count
    /// (submissions()): a relayer governance removes no longer counts.
    mapping(bytes32 => address[]) private _submitters;

    event PriceFeedUpdate(bytes32 indexed id, uint64 publishTime, int64 price, uint64 conf);
    event RelayerSet(address indexed relayer, bool on);
    event ThresholdSet(uint8 threshold);
    event GovernanceSet(address governance);
    event Submitted(bytes32 indexed id, bytes32 indexed update, address indexed relayer, uint8 count);

    error NotGovernance();
    error NotRelayer();
    error PriceFeedNotFound();
    error StalePrice();
    error InvalidUpdateData();
    error NoFee();

    constructor(address governance_, address[] memory relayers, uint8 threshold_) {
        require(governance_ != address(0), "governance");
        governance = governance_;
        for (uint256 i = 0; i < relayers.length; i++) _setRelayer(relayers[i], true);
        require(threshold_ >= 1, "threshold");
        threshold = threshold_;
        emit GovernanceSet(governance_);
        emit ThresholdSet(threshold_);
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setRelayer(address who, bool on) external onlyGov { _setRelayer(who, on); }
    function setThreshold(uint8 t) external onlyGov { require(t >= 1, "threshold"); threshold = t; emit ThresholdSet(t); }
    function setGovernance(address g) external onlyGov { require(g != address(0), "governance"); governance = g; emit GovernanceSet(g); }

    function _setRelayer(address who, bool on) private {
        require(who != address(0), "relayer");
        if (on != isRelayer[who]) { if (on) relayerCount += 1; else relayerCount -= 1; }
        isRelayer[who] = on;
        emit RelayerSet(who, on);
    }

    // ---- Pyth's interface ----

    function getUpdateFee(bytes[] calldata) external pure returns (uint256) { return 0; }

    function updatePriceFeeds(bytes[] calldata updateData) external payable {
        if (msg.value != 0) revert NoFee();
        if (!isRelayer[msg.sender]) revert NotRelayer();
        for (uint256 i = 0; i < updateData.length; i++) {
            (PriceFeed memory f, ) = abi.decode(updateData[i], (PriceFeed, uint64));
            if (f.id == bytes32(0) || f.price.publishTime > block.timestamp + MAX_FUTURE) revert InvalidUpdateData();
            if (f.price.publishTime <= _feeds[f.id].price.publishTime) continue; // older or same: ignored, as Pyth does
            bytes32 u = keccak256(updateData[i]);
            uint8 n = submissions(u);
            if (!submitted[u][msg.sender]) {
                submitted[u][msg.sender] = true;
                _submitters[u].push(msg.sender);
                n += 1;
                emit Submitted(f.id, u, msg.sender, n);
            }
            if (n < threshold) continue;
            _feeds[f.id] = f;
            emit PriceFeedUpdate(f.id, uint64(f.price.publishTime), f.price.price, f.price.conf);
        }
    }

    /// How many current relayers submitted this update (keccak256 of it).
    function submissions(bytes32 u) public view returns (uint8 n) {
        address[] storage s = _submitters[u];
        for (uint256 i = 0; i < s.length; i++) if (isRelayer[s[i]]) n += 1;
    }

    function priceFeedExists(bytes32 id) public view returns (bool) { return _feeds[id].price.publishTime != 0; }

    function getPriceUnsafe(bytes32 id) public view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].price;
    }

    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].emaPrice;
    }

    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory p) {
        p = getPriceUnsafe(id);
        if (block.timestamp > p.publishTime && block.timestamp - p.publishTime > age) revert StalePrice();
    }
}

contracts/ZetaphyQuests.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZearlyQ {
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

/// @title ZETAPHY Early quests: rewards in ZEARLY for things done on the ZETAPHY chain, each paid once per wallet
/// @notice The quests (first swap, liquidity, an Early Pass, staking…) are checked off chain from the chain's own
///         records (zetaphy-network/scripts/early.js quests); this contract pays from its ZEARLY balance and keeps,
///         on chain and for everyone to read, who was paid for which quest, so nobody is paid twice.
///         The operator (the quest job) sets each quest's reward and how many wallets it may pay, and pays.
///         It can take back only ZEARLY nobody was paid. Testnet; no value (zetaphy-chain/rewards/EARLY.md).
contract ZetaphyQuests {
    uint256 public constant MAX_BATCH = 300;

    IZearlyQ public immutable token;
    address public operator;

    struct Quest { uint256 reward; uint32 cap; uint32 count; }
    mapping(uint8 => Quest) public quests;
    mapping(uint8 => mapping(address => bool)) public paid;
    mapping(address => uint256) public earned;

    event OperatorSet(address operator);
    event QuestSet(uint8 indexed quest, uint256 reward, uint32 cap);
    event QuestPaid(uint8 indexed quest, address indexed to, uint256 reward);
    event Withdrawn(address to, uint256 amount);

    error NotOperator();
    error ZeroAddress();
    error BadBatch();
    error NoQuest();
    error TransferFailed();

    modifier onlyOperator() { if (msg.sender != operator) revert NotOperator(); _; }

    constructor(address token_, address operator_) {
        if (token_ == address(0) || operator_ == address(0)) revert ZeroAddress();
        token = IZearlyQ(token_);
        operator = operator_;
        emit OperatorSet(operator_);
    }

    function setOperator(address o) external onlyOperator {
        if (o == address(0)) revert ZeroAddress();
        operator = o;
        emit OperatorSet(o);
    }

    /// @notice A quest's reward per wallet and the most wallets it pays in all (cap 0 = closed).
    function setQuest(uint8 q, uint256 reward, uint32 cap) external onlyOperator {
        quests[q].reward = reward;
        quests[q].cap = cap;
        emit QuestSet(q, reward, cap);
    }

    /// @notice Pays quest `q` to every wallet in `to` not paid for it yet (others are skipped: re-runs are safe),
    ///         until the quest's cap. Returns how many were paid.
    function pay(uint8 q, address[] calldata to) external onlyOperator returns (uint256 n) {
        if (to.length == 0 || to.length > MAX_BATCH) revert BadBatch();
        Quest storage s = quests[q];
        if (s.reward == 0) revert NoQuest();
        for (uint256 i; i < to.length && s.count < s.cap; ++i) {
            address a = to[i];
            if (a == address(0) || paid[q][a]) continue;
            paid[q][a] = true;
            s.count += 1;
            earned[a] += s.reward;
            n++;
            if (!token.transfer(a, s.reward)) revert TransferFailed();
            emit QuestPaid(q, a, s.reward);
        }
    }

    /// @notice Which of quests 0..n-1 a wallet has been paid for (for the hub's Early page).
    function progress(address a, uint8 n) external view returns (bool[] memory done) {
        done = new bool[](n);
        for (uint8 i; i < n; ++i) done[i] = paid[i][a];
    }

    /// @notice Takes back ZEARLY nobody was paid (e.g. after the quests end).
    function withdraw(address to, uint256 amount) external onlyOperator {
        if (to == address(0)) revert ZeroAddress();
        if (!token.transfer(to, amount)) revert TransferFailed();
        emit Withdrawn(to, amount);
    }
}

contracts/ZkIdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZkPoseidonT3 {
    function poseidon(uint256[2] calldata x) external pure returns (uint256);
}

interface IZkIdentityVerifier {
    function verifyProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256[5] calldata pub)
        external view returns (bool);
}

interface IZkLabels {
    function labelOf(address account) external view returns (uint8);
    function humans(address account) external view returns (uint64 validUntil, uint8 method, bytes32 credentialHash, address attester);
}

interface IZkVouch {
    function levelOf(address account) external view returns (uint8);
}

/// @title ZkIdentityRegistry: private identities for labelled humans (testnet)
/// @notice docs/future/zk-identity.md. An account with a HUMAN label (LabelRegistry: a passkey checked on chain or by an
///   approved attester) registers an identity commitment C = Poseidon(secret, nullifierKey) that it made in its
///   browser. The registry stores the leaf Poseidon(C, level) in a Poseidon Merkle tree (depth 20), where level is
///   the account's uniqueness level when it registered or was last synced: 1 passkey human, 2 vouched unique human
///   (VouchRegistry; 1 if no VouchRegistry is set).
///   Later the person proves with a Groth16 proof (ZkIdentityVerifier) "my leaf is in the tree, my level >= X" and
///   reveals only nullifier = Poseidon(nullifierKey, scope), one per person per scope (PrivateAirdrop, PrivatePoll).
///
///   Which accounts are members is PUBLIC (registration is a transaction from the account). What is hidden is which
///   member made a given proof, and whether two proofs in different scopes came from the same member.
///
///   Binding rules (against making many identities from one label):
///   - an account keeps its first commitment forever: it can never register a second one;
///   - a passkey (credentialHash) is bound forever to the first commitment registered with it: moving the passkey to
///     a new account lets that account carry the SAME commitment (same nullifiers), never a new one;
///   - a commitment is in the tree at most once (one active account).
///   So a new identity needs a new account AND a new passkey (and, for level 2, new vouches): the anti-sybil
///   strength is exactly that of the labels and vouches (a person can make many passkeys; level 1 is a speed bump).
///
///   Labels expire and levels change: sync(account), callable by anyone, sets the leaf to the account's current
///   level, or removes it (leaf 0) when the account no longer holds a human label. Until someone calls it, the old
///   leaf stays provable. Replaced roots stay valid for rootTtl seconds, so proofs in flight survive new
///   registrations (and a removed member can still prove against a root younger than rootTtl).
///
///   Scopes: each app registers its scopes here (first come, first served), so two apps never share a nullifier
///   space by accident.
contract ZkIdentityRegistry {
    uint256 public constant SNARK_FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617;
    uint256 public constant DEPTH = 20;
    uint8 public constant HUMAN = 1;

    IZkPoseidonT3 public immutable poseidon;
    IZkIdentityVerifier public immutable verifier;
    IZkLabels public immutable labels;
    IZkVouch public vouch;
    address public governance;
    uint64 public rootTtl;

    struct Member {
        uint256 commitment;
        uint32 index;
        uint8 level;  // 0 = not in the tree now
        bool active;
    }

    mapping(address => Member) public memberOf;
    mapping(bytes32 => uint256) public credentialCommitment; // passkey hash -> the commitment it is bound to
    mapping(uint256 => address) public commitmentAccount;    // commitment -> the account that holds it
    mapping(uint256 => address) public scopeOwner;
    mapping(uint256 => uint64) public rootReplacedAt;        // when a root stopped being the current one
    mapping(uint256 => bool) public rootSeen;
    uint256 public root;
    uint256 public leafCount;
    uint256[21] private zeros;                                // zeros[h]: an empty subtree of height h
    mapping(uint256 => uint256) private nodes;                // (h << 32) | index -> node (0 = empty)

    event Registered(address indexed account, uint256 indexed commitment, uint256 index, uint8 level, uint256 root);
    event Synced(address indexed account, uint256 index, uint8 level, uint256 root);
    event LeafSet(uint256 indexed index, uint256 leaf, uint256 root);
    event ScopeRegistered(uint256 indexed scope, address indexed owner);
    event ConfigSet(address vouch, uint64 rootTtl);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotHuman();
    error BadCommitment();
    error AccountBound(uint256 commitment);
    error PasskeyBound(uint256 commitment);
    error CommitmentTaken(address account);
    error AlreadyMember();
    error NotMember();
    error Unchanged();
    error TreeFull();
    error ScopeTaken(address owner);
    error BadScope();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(IZkPoseidonT3 poseidon_, IZkIdentityVerifier verifier_, IZkLabels labels_, IZkVouch vouch_, address governance_, uint64 rootTtl_) {
        poseidon = poseidon_;
        verifier = verifier_;
        labels = labels_;
        vouch = vouch_;
        governance = governance_;
        rootTtl = rootTtl_;
        uint256 z = 0;
        for (uint256 h = 0; h <= DEPTH; h++) {
            zeros[h] = z;
            z = _hash(z, z);
        }
        root = zeros[DEPTH];
        rootSeen[root] = true;
    }

    // ------------------------------------------------------------- reading

    /// The level `account` would be registered at now: 0 (no human label, or an agent), 1 or 2.
    function levelNow(address account) public view returns (uint8) {
        if (labels.labelOf(account) != HUMAN) return 0;
        if (address(vouch) == address(0)) return 1;
        uint8 l = vouch.levelOf(account);
        return l == 0 ? 1 : l;
    }

    /// The current root, or a replaced one younger than rootTtl.
    function isValidRoot(uint256 r) public view returns (bool) {
        if (r == root) return true;
        return rootSeen[r] && rootReplacedAt[r] != 0 && block.timestamp <= uint256(rootReplacedAt[r]) + rootTtl;
    }

    function zeroAt(uint256 h) external view returns (uint256) {
        return zeros[h];
    }

    /// Leaves [from, from + count) (0 = empty or removed), for provers rebuilding the tree locally.
    function leavesRange(uint256 from, uint256 count) external view returns (uint256[] memory out) {
        if (from >= leafCount) return new uint256[](0);
        if (count > leafCount - from) count = leafCount - from;
        out = new uint256[](count);
        for (uint256 i = 0; i < count; i++) out[i] = nodes[from + i];
    }

    /// Checks a membership proof: root known and recent, level >= minLevel, nullifier for `scope`, bound to `signalHash`.
    /// proof = [a0, a1, b00, b01, b10, b11, c0, c1] in the Solidity verifier's order (zkid-core.js proofWords).
    function verify(uint256 root_, uint256 nullifier, uint256 scope, uint256 signalHash, uint256 minLevel, uint256[8] calldata proof)
        public view returns (bool)
    {
        if (!isValidRoot(root_) || minLevel == 0) return false;
        return verifier.verifyProof(
            [proof[0], proof[1]], [[proof[2], proof[3]], [proof[4], proof[5]]], [proof[6], proof[7]],
            [root_, nullifier, scope, signalHash, minLevel]
        );
    }

    // ------------------------------------------------------------- members

    /// Registers the caller's identity commitment (made in its browser; reveals nothing about the secret).
    function register(uint256 commitment) external {
        if (commitment == 0 || commitment >= SNARK_FIELD) revert BadCommitment();
        uint8 level = levelNow(msg.sender);
        if (level == 0) revert NotHuman();
        Member storage m = memberOf[msg.sender];
        if (m.active) revert AlreadyMember();
        if (m.commitment != 0 && m.commitment != commitment) revert AccountBound(m.commitment);
        (, , bytes32 cred, ) = labels.humans(msg.sender);
        uint256 bound = credentialCommitment[cred];
        if (bound != 0 && bound != commitment) revert PasskeyBound(bound);
        address holder = commitmentAccount[commitment];
        if (holder != address(0) && holder != msg.sender) {
            _sync(holder); // drops the old holder if it lost its label (e.g. the passkey moved here)
            if (memberOf[holder].active) revert CommitmentTaken(holder);
        }
        credentialCommitment[cred] = commitment;
        commitmentAccount[commitment] = msg.sender;
        uint256 index;
        if (m.commitment == commitment) {
            index = m.index; // back after a removal: the same slot
        } else {
            index = leafCount;
            if (index >= 2 ** DEPTH) revert TreeFull();
            leafCount = index + 1;
        }
        memberOf[msg.sender] = Member({commitment: commitment, index: uint32(index), level: level, active: true});
        uint256 r = _setLeaf(index, _hash(commitment, level));
        emit Registered(msg.sender, commitment, index, level, r);
    }

    /// Sets `account`'s leaf to its level now, or removes it if it no longer qualifies. Anyone may call it.
    function sync(address account) external {
        Member storage m = memberOf[account];
        if (!m.active) revert NotMember();
        if (!_sync(account)) revert Unchanged();
    }

    function _sync(address account) private returns (bool changed) {
        Member storage m = memberOf[account];
        if (!m.active) return false;
        uint8 level = levelNow(account);
        if (level != 0) {
            // the account's passkey now may be bound to another identity: it no longer qualifies with this one
            (, , bytes32 cred, ) = labels.humans(account);
            uint256 bound = credentialCommitment[cred];
            if (bound != 0 && bound != m.commitment) level = 0;
        }
        if (level == m.level) return false;
        m.level = level;
        uint256 r;
        if (level == 0) {
            m.active = false;
            r = _setLeaf(m.index, 0);
        } else {
            r = _setLeaf(m.index, _hash(m.commitment, level));
        }
        emit Synced(account, m.index, level, r);
        return true;
    }

    // ------------------------------------------------------------- scopes

    /// Claims `scope` for the caller (an app contract). Nullifiers are per scope: one owner per scope.
    function registerScope(uint256 scope) external {
        if (scope == 0 || scope >= SNARK_FIELD) revert BadScope();
        address o = scopeOwner[scope];
        if (o != address(0)) revert ScopeTaken(o);
        scopeOwner[scope] = msg.sender;
        emit ScopeRegistered(scope, msg.sender);
    }

    // ------------------------------------------------------------- governance

    function setConfig(IZkVouch vouch_, uint64 rootTtl_) external onlyGovernance {
        vouch = vouch_;
        rootTtl = rootTtl_;
        emit ConfigSet(address(vouch_), rootTtl_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- tree

    function _hash(uint256 a, uint256 b) private view returns (uint256) {
        return poseidon.poseidon([a, b]);
    }

    function _setLeaf(uint256 index, uint256 leaf) private returns (uint256 r) {
        uint256 node = leaf;
        uint256 i = index;
        for (uint256 h = 0; h < DEPTH; h++) {
            nodes[(h << 32) | i] = node;
            uint256 sib = nodes[(h << 32) | (i ^ 1)];
            if (sib == 0) sib = zeros[h];
